WITH duplicates AS (
  SELECT id
  FROM (
    SELECT id,
           ROW_NUMBER() OVER (PARTITION BY email, name ORDER BY id) AS rn
    FROM users
  ) t
  WHERE t.rn > 1
)
DELETE FROM users WHERE id IN (SELECT id FROM duplicates);

CREATE TABLE departments (
  id INT PRIMARY KEY,
  name TEXT
);

CREATE TABLE employees (
  id INT PRIMARY KEY,
  name TEXT,
  department_id INT REFERENCES departments(id),
  salary NUMERIC
);

CREATE TABLE sales (
  id serial PRIMARY KEY,
  sale_date date NOT NULL,
  amount numeric NOT NULL
);

CREATE TABLE user_activity (
  user_id INTEGER,
  activity_date DATE
);

CREATE TABLE orders (
  id SERIAL PRIMARY KEY,
  user_id INTEGER NOT NULL,
  total NUMERIC NOT NULL
);

CREATE TABLE visits (user_id INT, visited_at TIMESTAMP);
CREATE TABLE signups (user_id INT, signed_up_at TIMESTAMP);
CREATE TABLE purchases (user_id INT, purchased_at TIMESTAMP);

CREATE TABLE employees (
  id INT PRIMARY KEY,
  name TEXT NOT NULL,
  manager_id INT REFERENCES employees(id)
);

