SELECT id AS gap_start, LAG(id) OVER (ORDER BY id) AS prev_id
FROM items
WHERE id - LAG(id) OVER (ORDER BY id) > 1;

CREATE TABLE orders (
  id SERIAL PRIMARY KEY,
  customer_id INTEGER,
  order_date DATE,
  amount NUMERIC
);

CREATE TABLE customers (
  customer_id SERIAL PRIMARY KEY,
  name TEXT NOT NULL
);

CREATE TABLE customer_addresses (
  address_id SERIAL PRIMARY KEY,
  customer_id INTEGER REFERENCES customers(customer_id),
  address TEXT NOT NULL,
  valid_from DATE NOT NULL,
  valid_to DATE,
  is_current BOOLEAN NOT NULL DEFAULT TRUE
);

-- When a customer's address changes:
BEGIN;

UPDATE customer_addresses
SET valid_to = CURRENT_DATE - INTERVAL '1 day', is_current = FALSE
WHERE customer_id = 1 AND is_current = TRUE;

INSERT INTO customer_addresses (customer_id, address, valid_from, is_current)
VALUES (1, '123 New St', CURRENT_DATE, TRUE);

COMMIT;
